/* HEXA BATTLEGROUNDS upgrade3 — PART 20 OF 22. For databases that already ran supabase/upgrade-2 (open world); Run in order. Safe to re-run. */ create or replace function _shift_arena(p_arena uuid, p_delta interval) returns void language plpgsql as $$ begin update arenas set shuttle_departed_at = shuttle_departed_at + p_delta, shuttle_arrive_at = shuttle_arrive_at + p_delta, roles_deadline = roles_deadline + p_delta, play_started_at = play_started_at + p_delta, zone_next_at = zone_next_at + p_delta, last_airdrop_at = last_airdrop_at + p_delta, phase_started_at = phase_started_at + p_delta, phase_next_at = phase_next_at + p_delta, red_at = red_at + p_delta, last_red_at = last_red_at + p_delta, auto_next_at = auto_next_at + p_delta, overlay = case when overlay ? 'match' then jsonb_set(overlay, '{match,next_at}', coalesce(to_jsonb((overlay #>> '{match,next_at}')::timestamptz + p_delta), 'null'::jsonb)) else overlay end where id = p_arena; update mission_instances set deadline = deadline + p_delta, fallback_at = fallback_at + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update battles set deadline = deadline + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update sync_rounds set deadline = deadline + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update airdrops set expires_at = expires_at + p_delta, spawned_at = spawned_at + p_delta where arena_id = p_arena and status = 'open'; update alliances set expires_at = expires_at + p_delta, created_at = created_at + p_delta where arena_id = p_arena and status in ('proposed', 'active'); update story_events set expires_at = expires_at + p_delta where arena_id = p_arena and expires_at > now(); update teams set zone_hit_at = zone_hit_at + p_delta, travel_started_at = travel_started_at + p_delta, travel_arrive_at = travel_arrive_at + p_delta, recovery_deadline = recovery_deadline + p_delta, attack_cooldown_until = attack_cooldown_until + p_delta, protected_until = protected_until + p_delta, jammed_until = jammed_until + p_delta, scan_until = scan_until + p_delta where arena_id = p_arena; perform _zone_publish(p_arena); end $$;
